import torch


def _resolve_dtype(d):
    if isinstance(d, torch.dtype):
        return d
    return getattr(torch, str(d).replace("torch.", ""))


def run(inp, target, pos_weight, reduction):
    ref_inp = inp.to(torch.float64)
    ref_target = target.to(torch.float64)
    ref_pos_weight = pos_weight.to(torch.float64)
    return torch.binary_cross_entropy_with_logits(ref_inp, ref_target, pos_weight=ref_pos_weight, reduction=reduction)


def gen_inputs(ctx, device):
    tshape = ctx["target__shape"]
    tdtype = _resolve_dtype(ctx["target__dtype"])
    pshape = ctx["pos_weight__shape"]
    pdtype = _resolve_dtype(ctx["pos_weight__dtype"])
    return {
        "target": torch.rand(tshape, dtype=tdtype, device=device),
        "pos_weight": torch.rand(pshape, dtype=pdtype, device=device),
    }
